[
 {
  "id": "BR-CBTRN02C-001",
  "title": "Reject transaction whose card number is not in the card cross-reference file",
  "summary": "Each daily transaction's card number is looked up in the card cross-reference file. If the card isn't found, the transaction gets reason 100 'INVALID CARD NUMBER FOUND', the account lookup is skipped and the transaction goes to the reject file instead of being posted.",
  "given": [
   {
    "text": "Before each transaction is validated, the fail reason is set to 0 and the reason description is set to spaces.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-VALIDATION-FAIL-REASON-DESC"
    ],
    "literals": [
     "0"
    ]
   },
   {
    "text": "The transaction's card number is used as the key for reading the card cross-reference file.",
    "fields": [
     "DALYTRAN-CARD-NUM",
     "FD-XREF-CARD-NUM",
     "CARD-XREF-RECORD"
    ],
    "literals": []
   }
  ],
  "when": [
   {
    "text": "No cross-reference record exists for the card number (INVALID KEY on the read).",
    "fields": [
     "CARD-XREF-RECORD"
    ],
    "literals": []
   }
  ],
  "then": [
   {
    "text": "The fail reason is set to 100.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON"
    ],
    "literals": [
     "100"
    ]
   },
   {
    "text": "The reason description is set to 'INVALID CARD NUMBER FOUND'.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON-DESC"
    ],
    "literals": [
     "INVALID CARD NUMBER FOUND"
    ]
   },
   {
    "text": "The account lookup and the account checks are skipped because the fail reason is no longer 0.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON"
    ],
    "literals": [
     "0"
    ]
   },
   {
    "text": "The transaction is not posted. The reject count goes up by 1 and a reject record is written.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-REJECT-COUNT"
    ],
    "literals": [
     "0",
     "1"
    ]
   }
  ]
 },
 {
  "id": "BR-CBTRN02C-002",
  "title": "Reject transaction whose cross-referenced account does not exist",
  "summary": "Once the card is found, the program looks up the account ID from the card cross-reference record in the account file. If no account record exists, the transaction gets reason 101 'ACCOUNT RECORD NOT FOUND' and is rejected. The over-limit and expiration checks do not run.",
  "given": [
   {
    "text": "The card cross-reference lookup succeeded, so the fail reason is still 0.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON"
    ],
    "literals": [
     "0"
    ]
   },
   {
    "text": "The account file is read using the account ID from the cross-reference record as the key.",
    "fields": [
     "XREF-ACCT-ID",
     "FD-ACCT-ID",
     "ACCOUNT-RECORD"
    ],
    "literals": []
   }
  ],
  "when": [
   {
    "text": "No account record exists for that account ID (INVALID KEY on the read).",
    "fields": [
     "ACCOUNT-RECORD"
    ],
    "literals": []
   }
  ],
  "then": [
   {
    "text": "The fail reason is set to 101.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON"
    ],
    "literals": [
     "101"
    ]
   },
   {
    "text": "The reason description is set to 'ACCOUNT RECORD NOT FOUND'.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON-DESC"
    ],
    "literals": [
     "ACCOUNT RECORD NOT FOUND"
    ]
   },
   {
    "text": "The credit-limit check (reason 102) and the expiration check (reason 103) are skipped. They only run in the NOT INVALID KEY branch, when the account record is found.",
    "fields": [
     "ACCT-CREDIT-LIMIT",
     "WS-TEMP-BAL",
     "ACCT-EXPIRAION-DATE"
    ],
    "literals": [
     "102",
     "103"
    ]
   },
   {
    "text": "The transaction is not posted. The reject count goes up by 1 and a reject record is written.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-REJECT-COUNT"
    ],
    "literals": [
     "0",
     "1"
    ]
   }
  ]
 },
 {
  "id": "BR-CBTRN02C-003",
  "title": "Reject over-limit transaction based on current-cycle credit minus debit plus transaction amount",
  "summary": "For a found account, the program calculates current-cycle credit minus current-cycle debit plus the transaction amount. If the credit limit is less than the result, it sets reason 102 'OVERLIMIT TRANSACTION' and the transaction is rejected. The account's current balance is not used, and the result is held in a field with fewer integer digits than the account fields.",
  "given": [
   {
    "text": "The account record was found for the cross-referenced account ID.",
    "fields": [
     "ACCOUNT-RECORD"
    ],
    "literals": []
   },
   {
    "text": "The credit limit, current-cycle credit and current-cycle debit are each signed amounts with 10 integer digits and 2 decimals.",
    "fields": [
     "ACCT-CREDIT-LIMIT",
     "ACCT-CURR-CYC-CREDIT",
     "ACCT-CURR-CYC-DEBIT"
    ],
    "literals": []
   },
   {
    "text": "The working balance holds only 9 integer digits and 2 decimals. Integer digits above the 9th are dropped when the result is stored (no ON SIZE ERROR is coded).",
    "fields": [
     "WS-TEMP-BAL"
    ],
    "literals": []
   }
  ],
  "when": [
   {
    "text": "The working balance is calculated as current-cycle credit minus current-cycle debit plus the transaction amount.",
    "fields": [
     "WS-TEMP-BAL",
     "ACCT-CURR-CYC-CREDIT",
     "ACCT-CURR-CYC-DEBIT",
     "DALYTRAN-AMT"
    ],
    "literals": []
   },
   {
    "text": "The account credit limit is less than the working balance. If the limit is equal to or greater than the balance, this check passes.",
    "fields": [
     "ACCT-CREDIT-LIMIT",
     "WS-TEMP-BAL"
    ],
    "literals": []
   }
  ],
  "then": [
   {
    "text": "The fail reason is set to 102.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON"
    ],
    "literals": [
     "102"
    ]
   },
   {
    "text": "The reason description is set to 'OVERLIMIT TRANSACTION'.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON-DESC"
    ],
    "literals": [
     "OVERLIMIT TRANSACTION"
    ]
   },
   {
    "text": "Because the fail reason is no longer 0, the transaction is not posted. The reject count goes up by 1 and a reject record is written.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-REJECT-COUNT"
    ],
    "literals": [
     "0",
     "1"
    ]
   }
  ]
 },
 {
  "id": "BR-CBTRN02C-006",
  "title": "Posting updates or creates the transaction category balance record",
  "summary": "Each validated daily transaction is added to a category balance record keyed by account ID, transaction type code and category code. If no record exists for that key, a new one is created with the transaction amount as its balance. If one exists, the amount is added to its balance and the record is rewritten.",
  "given": [
   {
    "text": "The daily transaction passed validation (no failure reason was set), so it is posted.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON"
    ],
    "literals": []
   },
   {
    "text": "The category balance key is the account ID from the card cross-reference, plus the transaction's type code and category code.",
    "fields": [
     "XREF-ACCT-ID",
     "FD-TRANCAT-ACCT-ID",
     "DALYTRAN-TYPE-CD",
     "FD-TRANCAT-TYPE-CD",
     "DALYTRAN-CAT-CD",
     "FD-TRANCAT-CD"
    ],
    "literals": []
   },
   {
    "text": "The category balance is a signed amount with 9 integer digits and 2 decimal places.",
    "fields": [
     "TRAN-CAT-BAL"
    ],
    "literals": []
   }
  ],
  "when": [
   {
    "text": "The program reads the category balance file by that key. If no record is found, it sets the create flag to Y; otherwise the flag stays N.",
    "fields": [
     "WS-CREATE-TRANCAT-REC",
     "TCATBAL-FILE",
     "TRAN-CAT-BAL-RECORD"
    ],
    "literals": [
     "N",
     "Y"
    ]
   }
  ],
  "then": [
   {
    "text": "If the create flag is Y, a new record is built. Otherwise the existing record is updated.",
    "fields": [
     "WS-CREATE-TRANCAT-REC"
    ],
    "literals": [
     "Y"
    ]
   },
   {
    "text": "Create case: the record is initialized so the balance starts at zero.",
    "fields": [
     "TRAN-CAT-BAL-RECORD"
    ],
    "literals": []
   },
   {
    "text": "Create case: the account ID, type code and category code are copied into the new record's key fields.",
    "fields": [
     "XREF-ACCT-ID",
     "TRANCAT-ACCT-ID",
     "DALYTRAN-TYPE-CD",
     "TRANCAT-TYPE-CD",
     "DALYTRAN-CAT-CD",
     "TRANCAT-CD"
    ],
    "literals": []
   },
   {
    "text": "Create case: the transaction amount, with its sign, is added to the zero balance and the new record is written to the category balance file.",
    "fields": [
     "DALYTRAN-AMT",
     "TRAN-CAT-BAL",
     "FD-TRAN-CAT-BAL-RECORD"
    ],
    "literals": []
   },
   {
    "text": "Update case: the transaction amount, with its sign, is added to the existing balance and the record is rewritten in place.",
    "fields": [
     "DALYTRAN-AMT",
     "TRAN-CAT-BAL",
     "FD-TRAN-CAT-BAL-RECORD"
    ],
    "literals": []
   },
   {
    "text": "Update case: the ADD to the balance has no ON SIZE ERROR clause. If the sum has more than 9 integer digits, the high-order digits are silently dropped.",
    "fields": [
     "DALYTRAN-AMT",
     "TRAN-CAT-BAL"
    ],
    "literals": []
   }
  ]
 },
 {
  "id": "BR-CBTRN02C-007",
  "title": "Posting updates the account balances and writes the transaction record",
  "summary": "After the category balance update, the transaction amount is added to the account's current balance. It is also added to the cycle credit total if the amount is zero or more, or to the cycle debit total if it is negative. The account record is then rewritten. Next, a transaction record is written: it copies the daily transaction's fields and adds a processing timestamp. If the account rewrite fails, reason 109 is set, but the transaction is still written and is not counted as rejected.",
  "given": [
   {
    "text": "The account record being updated is the one read during validation, using the account ID from the card cross-reference.",
    "fields": [
     "XREF-ACCT-ID",
     "FD-ACCT-ID",
     "ACCOUNT-FILE",
     "ACCOUNT-RECORD"
    ],
    "literals": []
   },
   {
    "text": "The account's current balance is a signed amount with 10 integer digits and 2 decimal places.",
    "fields": [
     "ACCT-CURR-BAL"
    ],
    "literals": []
   },
   {
    "text": "The cycle credit and cycle debit totals are signed amounts with 10 integer digits and 2 decimal places.",
    "fields": [
     "ACCT-CURR-CYC-CREDIT",
     "ACCT-CURR-CYC-DEBIT"
    ],
    "literals": []
   },
   {
    "text": "The steps always run in this order, with no condition between them: category balance update, account update, then the transaction write.",
    "fields": [
     "2700-UPDATE-TCATBAL",
     "2800-UPDATE-ACCOUNT-REC",
     "2900-WRITE-TRANSACTION-FILE"
    ],
    "literals": []
   }
  ],
  "when": [
   {
    "text": "A validated transaction is posted, and its amount is checked to see whether it is zero or more, or negative.",
    "fields": [
     "DALYTRAN-AMT"
    ],
    "literals": []
   }
  ],
  "then": [
   {
    "text": "The transaction amount, with its sign, is always added to the account's current balance.",
    "fields": [
     "DALYTRAN-AMT",
     "ACCT-CURR-BAL"
    ],
    "literals": []
   },
   {
    "text": "If the amount is zero or positive, it is added to the cycle credit total. If it is negative, it is added as a negative value to the cycle debit total, so that total goes down.",
    "fields": [
     "DALYTRAN-AMT",
     "ACCT-CURR-CYC-CREDIT",
     "ACCT-CURR-CYC-DEBIT"
    ],
    "literals": []
   },
   {
    "text": "The updated account record is rewritten to the account file.",
    "fields": [
     "FD-ACCTFILE-REC",
     "ACCOUNT-RECORD"
    ],
    "literals": []
   },
   {
    "text": "If the rewrite finds no record, reason code 109 and the text ACCOUNT RECORD NOT FOUND are set.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-VALIDATION-FAIL-REASON-DESC"
    ],
    "literals": [
     "109",
     "ACCOUNT RECORD NOT FOUND"
    ]
   },
   {
    "text": "The reason code is only checked before posting, to decide between posting and rejecting. A code of 109 set during posting therefore does not add to the reject count and does not write a reject record.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-REJECT-COUNT"
    ],
    "literals": [
     "0"
    ]
   },
   {
    "text": "Before the next daily transaction is validated, the reason code is reset to 0 and the reason text to spaces.",
    "fields": [
     "WS-VALIDATION-FAIL-REASON",
     "WS-VALIDATION-FAIL-REASON-DESC"
    ],
    "literals": [
     "0"
    ]
   },
   {
    "text": "The transaction record copies these fields from the daily transaction: ID, type code, category code, source, description, amount, merchant ID, merchant name, merchant city, merchant ZIP, card number and original timestamp.",
    "fields": [
     "DALYTRAN-ID",
     "TRAN-ID",
     "DALYTRAN-TYPE-CD",
     "TRAN-TYPE-CD",
     "DALYTRAN-CAT-CD",
     "TRAN-CAT-CD",
     "DALYTRAN-SOURCE",
     "TRAN-SOURCE",
     "DALYTRAN-DESC",
     "TRAN-DESC",
     "DALYTRAN-AMT",
     "TRAN-AMT",
     "DALYTRAN-MERCHANT-ID",
     "TRAN-MERCHANT-ID",
     "DALYTRAN-MERCHANT-NAME",
     "TRAN-MERCHANT-NAME",
     "DALYTRAN-MERCHANT-CITY",
     "TRAN-MERCHANT-CITY",
     "DALYTRAN-MERCHANT-ZIP",
     "TRAN-MERCHANT-ZIP",
     "DALYTRAN-CARD-NUM",
     "TRAN-CARD-NUM",
     "DALYTRAN-ORIG-TS",
     "TRAN-ORIG-TS"
    ],
    "literals": []
   },
   {
    "text": "The transaction record's processing timestamp is set to the formatted timestamp built just before it is moved in.",
    "fields": [
     "DB2-FORMAT-TS",
     "TRAN-PROC-TS"
    ],
    "literals": []
   },
   {
    "text": "The timestamp is built from the current system date and time.",
    "fields": [
     "COBOL-TS"
    ],
    "literals": []
   },
   {
    "text": "The current date and time are split into year (4 characters) followed by month, day, hour, minute, second and fraction (2 characters each).",
    "fields": [
     "COBOL-TS",
     "COB-YYYY",
     "COB-MM",
     "COB-DD",
     "COB-HH",
     "COB-MIN",
     "COB-SS",
     "COB-MIL"
    ],
    "literals": []
   },
   {
    "text": "The 26-character timestamp is laid out as: year (4), separator, month (2), separator, day (2), separator, hour (2), separator, minute (2), separator, second (2), separator, fraction (2), then a 4-character tail.",
    "fields": [
     "DB2-FORMAT-TS",
     "DB2-YYYY",
     "DB2-STREEP-1",
     "DB2-MM",
     "DB2-STREEP-2",
     "DB2-DD",
     "DB2-STREEP-3",
     "DB2-HH",
     "DB2-DOT-1",
     "DB2-MIN",
     "DB2-DOT-2",
     "DB2-SS",
     "DB2-DOT-3",
     "DB2-MIL",
     "DB2-REST"
    ],
    "literals": []
   },
   {
    "text": "The date and time parts are copied in, the tail is set to 0000, the three date separators are set to '-' and the three time separators to '.'. The result is YYYY-MM-DD-HH.MM.SS.ff0000.",
    "fields": [
     "COB-YYYY",
     "DB2-YYYY",
     "COB-MM",
     "DB2-MM",
     "COB-DD",
     "DB2-DD",
     "COB-HH",
     "DB2-HH",
     "COB-MIN",
     "DB2-MIN",
     "COB-SS",
     "DB2-SS",
     "COB-MIL",
     "DB2-MIL",
     "DB2-REST",
     "DB2-STREEP-1",
     "DB2-STREEP-2",
     "DB2-STREEP-3",
     "DB2-DOT-1",
     "DB2-DOT-2",
     "DB2-DOT-3"
    ],
    "literals": [
     "0000",
     "-",
     "."
    ]
   },
   {
    "text": "The completed transaction record is written as a new record to the transaction file.",
    "fields": [
     "FD-TRANFILE-REC",
     "TRAN-RECORD"
    ],
    "literals": []
   },
   {
    "text": "The transaction file is an indexed file keyed on FD-TRANS-ID.",
    "fields": [
     "TRANSACT-FILE",
     "FD-TRANS-ID"
    ],
    "literals": []
